where.if:
AND (
    CAST(r.id AS CHAR) = #{q.q}
    OR r.match_id = #{q.q}
    OR r.league_name LIKE CONCAT('%', #{q.q}, '%')
    OR r.home_team LIKE CONCAT('%', #{q.q}, '%')
    OR r.guest_team LIKE CONCAT('%', #{q.q}, '%')
)

mapper.select:
AND r.model IN ('jiebao','nami') AND r.is_latest = 1 AND COALESCE(r.recommend_role, 'primary') = 'primary'
AND r.rate >= #{q.minRate}
AND r.result_status = 0
ORDER BY r.create_time DESC, r.id DESC LIMIT #{q.limit}


WHERE r.match_id = #{matchId}

    AND r.model = #{model}

ORDER BY r.is_latest DESC,
         r.create_time DESC,
         r.rate DESC,
         r.id DESC
